  FT["PH-H1348"] = {"id":"PH-H1348","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1514_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Barrio of Bayan-Bayanan, Municipality of Marikina, Province of Rizal, to Concepcion","orig":"An Act Changing the Name of the Barrio of Bayan-Bayanan, Municipality of Marikina, Province of Rizal, to Concepcion"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1514","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1514_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1348-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the barrio of Bayan-Bayanan, Municipality of Marikina, Province of Rizal, is changed to Concepcion."}},{"id":"PH-H1348-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
  FT["PH-H1349"] = {"id":"PH-H1349","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1515_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for a More Autonomous Government for Municipal Districts, Amending for the Purpose Article Six, Chapter Sixty-Four of the Administrative Code","orig":"An Act Providing for a More Autonomous Government for Municipal Districts, Amending for the Purpose Article Six, Chapter Sixty-Four of the Administrative Code"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1515","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1515_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1349-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Article six, Chapter sixty-four of the Administrative Code is amended to read as follows:\n\"ARTICLE VI Municipal Districts \"Sec. 2630. Special municipal governments. In localities the majorities of the inhabitants whereof have not progressed sufficiently in civilization to make it practicable to bring them under municipal government as provided in existing legislation, and whenever non-Christian settlements are so small or remote that their organization as barrios of municipalities is impracticable, there shall be organized municipal district governments in accordance with the provisions of this article.\n\"Sec. 2630-A. Classification of municipal districts. Municipal districts are divided into four classes, according to their receipts, as follows:\n\"(a) Municipal districts of the first class shall be those the annual receipts of which averaged three thousand pesos or more but less than four thousand pesos during the last four fiscal years, and shall have six councilors;\n\"(b) Municipal districts of the second class shall be those the annual receipts of which averaged two thousand pesos or more but less than three thousand pesos during the last four fiscal years, and shall have six councilors;\n\"(c) Municipal districts of the third class shall be those the annual receipts of which averaged one thousand five hundred pesos or more but less than two thousand pesos during the last four fiscal years, and shall have four councilors; and \"(d) Municipal districts of the third class shall be those the annual receipts of which averaged one thousand pesos or more but less than one thousand five hundred pesos during the last four fiscal years, and shall have four councilors.\n\"Any municipal district the average receipts of which are less than one thousand pesos shall be incorporated and merged with such adjacent municipal district as the provincial board concerned shall determine.\n\"Beginning with the fiscal year nineteen hundred fifty- seven and for each period of four consecutive fiscal years thereafter, the chief of local governments shall cause the classification of municipal districts in accordance with the provisions of the preceding paragraphs.\n\"Sec. 2630-B. Officials of the municipal districts. The mayor, vice-mayor and councilors of each municipal district shall be elected by the qualified voters thereof during every election for provincial and municipal officers in accordance with the provisions of the Revised Election Code. No person shall be eligible for the position of mayor, vice- mayor or councilors of a municipal district unless he has the corresponding qualifications prescribed by law for elective municipal officers.\n\"There shall also be in each municipal district a secretary, a treasurer and such other appointive officers and employees as the municipal district council shall deem necessary and provide for and the provincial board shall authorize.\n\"Sec. 2630-C. Salaries. Notwithstanding the provisions of the minimum wage law, the municipal district officers shall receive the following annual compensation:\n\"(a) In first class municipal districts mayor, five hundred forty pesos; vice-mayor and councilors, a per diem of three pesos; treasurer, four hundred eighty pesos; and secretary, four hundred twenty pesos;\n\"(b) In second class municipal districts mayor, four hundred eighty pesos; vice-mayor and councilors, a per diem of two pesos and fifty centavos; treasurer, four hundred twenty pesos; and secretary, three hundred sixty pesos;\n\"(c) In third class municipal districts mayor, four hundred twenty pesos; vice-mayor and councilors, a per diem of two pesos; treasurer, three hundred sixty pesos; and secretary, three hundred pesos;\n\"(d) In fourth class municipal districts-mayor, three hundred sixty pesos; vice-mayor and councilors, a per diem of one peso and fifty centavos; treasurer, three hundred pesos; and secretary, two hundred forty pesos.\n\"Sec. 2630-D. The mayor. The mayor shall be the chief executive officer of the municipal district and shall have the following general powers and duties:\n\"(a) Observance and enforcement of laws. He shall take care that all laws, ordinances, regulations, and resolutions in force and in the municipal district are duly observed and executed within its jurisdiction.\n\"(b) Authority over municipal district officers. He shall see that all other officers of the municipal district faithfully discharge their respective duties, and to that end may, with the approval of the provincial governor, cause to be instituted any appropriate criminal action or to take other proceedings to bring the attention of the proper superior officer to the derelictions of any municipal district official.\n\"(c) Recommendations to council. He shall give to the municipal district council from time to time such information and recommend such measures as he shall deem advantageous to the municipal district.\n\"(d) Meetings of council. He shall preside at all meetings of the municipal district council; shall have the right to vote on ordinances or other matters coming before the council only in the case of a tie vote; shall sign the secretary's record of the proceedings of each meeting of the council, at the same meeting at which the same is approved by the council; and shall sign all ordinances and resolutions.\n\"(e) Bonds, contracts, and so forth. He shall sign all bonds, contracts, and obligations of the municipal district, pursuant to a resolution of the municipal district council, duly approved by the provincial board in each instance, unless otherwise herein provided.\n\"(f) Appointments. He shall appoint, with the consent of the majority of all the members of the municipal district council, the municipal district secretary, and upon recommendation of the chief of office concerned, all non-elective municipal district officers and employees that may be provided for by law or by ordinance, with the exception of school teachers and the municipal district treasurer.\n\"(g) Nominations. He shall make all nominations at the first meeting of the municipal district council after assuming the duties of his office except for those offices and employments in which a vacancy may occur during his term. In case the council shall reject any of the nominations made by him, he shall be entitled to appeal to the provincial board, whose decision shall be final. In case a vacancy occurs in any of the above-named offices and employments during the term of office of the mayor, he shall submit a nomination to the municipal district council at the first regular meeting after the occurrence of the vacancy.\n\"(h) Public order, calamities, and so forth. He shall issue orders relating to the police or public safety, and orders for the purpose of avoiding conflagrations, floods, and the effects of storms or other public calamities.\n\"(i) Collection of taxes. He shall assist the provincial treasurer and his deputies in the collection of taxes.\n\"(j) Judicial powers. He shall act as ex-officio justice of the peace for the municipal district in the absence of the justice and auxiliary justice of the peace therein, subject to the provisions and limitations of general law. Fees collected by him while acting as justice of the peace shall be covered into the municipal district treasury.\n\"(k) Inspection of barrios. He shall at least once every three months visit every barrio within the municipal district.\n\"(l) Annual report. He shall, on or before the tenth day of January of each year, prepare and present to the provincial board an annual report covering the operations of the municipal district government during the preceding year.\n\"Sec. 2630-E. The vice-mayor. The vice-mayor shall be a member of the municipal district council and shall, during the temporary absence of the mayor from the municipal district or his disability for any reason, discharge the duties of his office and exercise all his powers; and in case of death, removal, or permanent disability of the mayor, the vice-mayor shall act as temporary mayor until a new mayor shall have been elected and shall have qualified.\n\"Sec. 2630-F. The municipal district treasurer. The municipal district treasurer shall, until otherwise provided by law, be appointed by the provincial treasurer, subject to the approval of the provincial board, and shall perform the following general powers and duties:\n\"(a) Receipts and accounts for moneys. He shall receive all moneys paid to the municipal district from any source whatever, and shall account for the same in accordance with law and administrative regulations.\n\"(b) Account to provincial auditor. He shall render such accounts as the provincial auditor may require of him.\n\"(c) Office keeping of money, and so forth. He shall have his office in the municipal district building and he shall keep in the municipal district steel safe, which it shall be the duty of the municipal district council to provide, all funds in his custody. Such money shall be kept separate and distinct from his own money, and he shall not be permitted to make profit out of public money or to lend or otherwise use it or to use the same in any method not authorized by law.\n\"(d) Deposit of funds. He shall deposit for safe keeping with the provincial treasurer such sums of money as he may deem necessary.\n\"(e) Custodian of municipal district property. He shall be the custodian of all municipal district property and shall keep a complete record thereof.\n\"(f) Annual report. He shall, during the first fifteen days of July of each year, prepare in duplicate itemized statements of the income and disbursements for the preceding fiscal year, one copy of which shall be transmitted to the provincial treasurer and the other to the municipal district council.\n\"(g) List of taxpayers. He shall, within ten days after the passage of the ordinance by the council for the payment of licenses or privilege taxes, prepare a list of the names of the persons whose business, if continued, would render them liable to the license or tax, and he shall transmit such list at once to the provincial treasurer to enable them more readily to detect persons failing to pay the license and privilege taxes for which they shall have become liable.\n\"(h) Requisitions. He shall make requisitions upon the provincial treasurer for necessary supplies or equipment, in accordance with the provisions of sub-section (h) of section two thousand six hundred and eleven hereof.\n\"(i) Civil register. He shall keep a civil register as prescribed by Act Numbered Thirty-seven hundred fifty-three.\n\"Sec. 2630-G. The municipal district secretary. The municipal district secretary shall have the following general powers and duties:\n\"(a) Council meeting. He shall act as secretary of the municipal district council, whose meetings it shall be his duty to attend.\n\"(b) Journal of proceedings. He shall record all ordinances passed by the municipal district council with the dates of the passage and publication of the same.\n\"(c) Seal. He shall keep the corporate seal and affix the same with his signature to all ordinances and other official acts of the mayor or council.\n\"(d) Posting. He shall cause each ordinance passed to be posted as herein provided.\n\"(e) Documents, and so forth. He shall have charge of all records and documents of the municipal district for which provisions is not otherwise made, and shall, on demand, furnish certified copies of all municipal records and documents and collect and receive therefor a fee of ten centavos per one hundred words which shall accrue to the municipal district treasury.\n\"(f) Ordinances, resolutions, and so forth. He shall, within thirty-six hours after any session of the council or the issuance of an order by the mayor, forward a correct and certified copy of each resolution and ordinance passed thereat, and of every order of the mayor, properly numbered, to the provincial board. He shall also, within the thirty-six hours aforesaid, forward to the provincial treasurer a copy of each resolution or ordinance authorizing or necessitating the collection of municipal district revenues. He shall translate or cause to be translated each ordinance into the dialect generally spoken in the municipal district and forward copies thereof to each municipal district councilor.\n\"The provincial board shall have the power to disapprove ordinances and resolutions of the municipal district on the same grounds as those provided for in the general law for regular municipalities. The decision made in pursuance of such power shall be final.\n\"(g) Other duties. He shall perform such other duties as the mayor or council may direct.\n\"Sec. 2630-H. Councilors. The councilor shall participate in the exercise of the powers vested in the municipal district council as a body and shall therein serve as the representative of the true interests of the people of the entire municipal district. As an individual officer, each councilor shall have the following general duties and powers:\n\"(a) Information for barrios. He shall keep the people of the barrio or barrios confided to his care by the council informed as to the acts of the council, or other governmental measures which directly concern them, by \"bandillo\" or other methods of appropriate or effective publication.\n\"(b) Recommendation to the council. He shall bring the special needs of the barrio or barrios under his care to the attention of the council and shall make such recommendations as he may deem necessary.\n\"(c) Important events. He shall promptly inform the mayor of any unusual or untoward event occurring within said barrio or barrios.\n\"(d) Lieutenant of barrio. He shall appoint not more than two lieutenants for the barrio or each of the barrios which come under his immediate supervision. A lieutenant of barrio shall serve without compensation, and shall report directly to the councilor appointing him. It shall be the duty of the lieutenant of barrio to assist the councilor in the performance of his ministerial duties in the barrio. The term of office of the lieutenant of barrio shall be that of the councilor appointing him.\n\"The qualifications for barrio lieutenant shall be the same as those required by law in regular municipalities.\n\"(e) Substitute lieutenant of barrio. He shall also appoint a substitute lieutenant of barrio, who shall take the place of the lieutenant of the barrio during the temporary absence or disability of the latter.\n\"Sec. 2631. The municipal district council. The municipal district council shall be composed of the mayor, as the presiding officer, the vice-mayor and the number of councilors prescribed in section two thousand six hundred thirty-A hereof. The council shall have the power, by ordinance or resolution:\n\"(a) Appropriations. To make, subject to the approval of the provincial board, necessary appropriations for the expenses of government of the municipal district, and fix in said appropriations, without regard to the provisions of the minimum wage law, the salaries of municipal district officers and employees, except as herein provided.\n\"(b) Property. To purchase, receive, hold real and personal property for the benefit of the municipal district and, subject to the approval of the provincial board, to sell, lease, convey and dispose of real property.\n\"(c) Levy, collections and expenditures of taxes. Subject to the approval of the provincial board, to provide for the levy and collection of taxes and other municipal district revenues, as provided by law, and apply the same to the payment of expenses of the municipal district in accordance with the appropriations.\n\"(d) Licenses and license fee. Subject to the approval of the provincial board, to prescribe licenses fixing the amount of the license fee for the following: hawkers, peddlers, hucksters, not including hucksters or peddlers who sell only native vegetables, fruits or foods, personally carried by the huckster or peddler, auctioneers, plumbers, barbers, tailor shops, bakeries, manicuring establishments, massage parlors, embalmers, collecting agencies, mercantile agencies, transportation companies and agencies, advertising agents, tattooers, hotels, clubs, restaurants, lodging- houses, livery stables, boarding stables, laundries, cleaning and dyeing establishments, establishments for the storage of highly combustible or explosive materials, public warehouses, circus and other similar parades, public vehicles, bicycles, horse races, bowling alleys, pawnbrokers, dealers in second-hand merchandise, junk dealers, billiard tables, theaters, theatrical performances and all other performances and places of amusement, shooting galleries, and merry-go round; to regulate and license dance halls, and the selling, giving away, or disposing, in any manner, of any intoxicating, spirituous, vinous, or fermented liquors; and to regulate and license signs, signboards, and billboards, displayed or maintained in any place exposed to public view, except those displayed at the place or places where the profession or business advertised thereby is in whole or in part conducted, and fix the sum to be paid for such licenses.\n\"If after due investigation the mayor shall decide that any person licensed under the provisions of this subsection is abusing his license and privilege to the injury of the public morals or peace, or that any place so licensed has been or is conducted in a disorderly or unlawful manner, or is a nuisance, or is permitted to be used as a resort for disorderly characters, criminals, or women of ill repute, he may by order summarily revoke such license, subject to appeal to the provincial board, whose action on the appeal shall be final. Such revocation shall operate to forfeit to the municipal district all sums which may have been paid for said license.\n\"(e) Regulations for conducting business. To make regulations for the conduct of the business of the persons and places named in subsection (d) of this section; to regulate the business and fix the location of blacksmith shops, foundries, steam boilers, steam engines, lumber yards, sawmills, and other establishments likely to endanger the public safety by giving rise to conflagrations or explosions; to regulate the storage and sale of gunpowder, tar, pitch, resin, coal, oil, gasoline, benzine, turpentine, nitroglycerine, petroleum, or any of the products thereof and of all other highly combustible or explosive materials.\n\"(f) Public Buildings. Subject to the approval of the provincial board, to provide for the erection or rental of public buildings necessary for the use of the municipal district.\n\"(g) Scholarships. To grant scholarships to male and female students in the municipal district, under such conditions as it may deem convenient to prescribe, subject to the approval of the provincial board and the chief of local governments.\n\"(h) Building regulations. To establish fire limits, and prescribe the kind of buildings and structures that may be erected within said limits, and the manner of constructing and repairing the same.\n\"(i) To prepare and lay out plans for streets, sections for public and private buildings, markets, playgrounds, cemeteries, plazas and schools to be approved by the National Planning Commission.\n\"(j) Fire department. To erect engine houses, and provide fire engines, hose carts, hooks and ladders, and other equipment for the prevention and extinguishment of fires, and to provide for the management and use of the same. Until further provision is made, the law providing for fire protection in municipalities having no paid fire department, except as to the number of authorized volunteer firemen, shall apply to all municipal districts.\n\"(k) Lights, fires, and fireworks. To regulate the use of lights in stables, shops, and other buildings and places, and to regulate or restrain the building of bonfires and the use of firecrackers, fireworks, torpedoes, and pyrotechnic displays.\n\"(l) Storms and calamities. To make suitable provisions to insure the public safety from conflagrations, the effects of storms, and other public calamities, and to provide relief for persons suffering from the same.\n\"(m) Waterworks and water supply. To maintain waterworks and artesian wells for the purpose of supplying water to the inhabitants of the municipal district, to purify the source of supply, and regulate the control and use of the water, and to fix and collect rents therefor; to regulate the construction, repair, and use of hydrants, pumps, cisterns, and reservoirs, and to prevent the waste of water.\n\"(n) Pounds Stray animals. To establish and maintain a municipal district pound and fix the fees for poundage; to regulate, restrict, or prohibit the running at large of domestic animals and fowls, and to provide for the distraining, impounding, and sale of the same for the penalty incurred and the cost of the proceedings, or for killing in the event of failure or sale; also to impose penalties upon the owners of said animals for the violation of any ordinance in relation thereto. Carabaos, horses, mules, asses, and all members of the bovine family shall, however, be disposed of in accordance with general law.\n\"(o) Burial of dead. To prohibit the burial of the dead within the centers of population of the municipal district and provide for their burial in such proper place and in such manner as the council may determine, subject to the provisions of the general law regulating burial grounds and cemeteries and governing funerals and the disposal of the dead.\n\"(p) Slaughterhouses and markets. Subject to the approval of the provincial board, to establish or authorize the establishment of slaughterhouses and markets, and inspect and regulate the use of the same; to provide for and regulate the keeping, preparation, and sale of meat, fruits, poultry, milk, fish, vegetables, and all other provisions or articles of food offered for sale.\n\"(q) Enforcement of health laws and regulations. To enforce health laws and regulations, and by ordinance to provide fines and penalties for violations of such regulations, subject to the approval of the provincial board; to adopt such other measures to prevent the introduction and spread of diseases as may, from time to time, be deemed desirable and necessary.\n\"(r) Nuisances. To declare, prevent, and abate nuisances.\n\"(s) Cockfighting. To regulate and license or prohibit cockfighting and to close cockpits subject to the provisions and restrictions of general law.\n\"(t) Police. To establish, maintain, and regulate a police force.\n\"(u) Disorderly houses, and so forth. To suppress houses of ill fame and other disorderly houses; to prohibit the printing, sale, or exhibition of immoral pictures, books, or publications of any description.\n\"(v) Gambling, riots, and breaches of the peace. To prevent and suppress riots, gambling, affrays, disturbances, and disorderly assemblies; to punish and prevent intoxication, fighting, quarreling, and all disorderly conduct; to make and enforce all necessary police ordinances, with the view to the confinement and reformation of vagrants, gamblers, disorderly persons, mendicants, and prostitutes, and persons convicted of violating any municipal district ordinance.\n\"(w) Penalties for violation of ordinances. To fix, subject to the approval of the provincial board, penalties for violation of ordinances, but no single penalty shall exceed a fine of two hundred pesos or imprisonment for two months, or both; imprisonment shall be imposed in lieu of unpaid fines at the rate of one day's imprisonment for every two pesos and fifty centavos of the fine. Persons undergoing imprisonment for violation of ordinances may be required to labor for the period of imprisonment upon public works of the municipal district in such manner as may be directed by the municipal district council. Whenever a person is imprisoned for non-payment of a fine he shall be released upon payment of such fine, less two pesos and fifty centavos per day for each day that he has been confined. Persons charged with violation of a municipal district ordinance who cannot be tried immediately after arrest shall be released by the chief of police or his authorized agents either upon personal recognizance or a cash bond not exceeding fifty per centum of the maximum fine provided in the ordinance.\n\"(x) General welfare clause. To make such further ordinances and regulations, not repugnant to law, as may be necessary to carry into effect and discharge the powers and duties conferred herein, and such as shall seem necessary, and proper to provide for the health and safety, promote the prosperity, improve the morals, peace, good order, comfort, and convenience of the municipal district and the inhabitants thereof, and for the protection of property therein; and enforce obedience thereto with such lawful fines or penalties as the municipal district council may prescribe under the provisions of subsection (w) of this section.\n\"The ordinances and resolutions approved by the council shall take effect as provided for in the Administrative Code for regular municipalities.\""}},{"id":"PH-H1349-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any fifth class municipality, the annual receipts of which shall fail to average four thousand pesos for four consecutive fiscal years shall ipso facto be classified as a first class municipal district and shall thereafter be governed by the provisions of Article six, Chapter sixty- four of the Administrative Code, as hereinabove amended. Similarly, any first class municipal district the annual receipts of which shall average more than four thousand pesos for four consecutive fiscal years shall ipso facto be classified as a fifth class municipality and shall thereafter be governed by the provisions of Articles one to five, Chapter sixty-four of the same Code."}},{"id":"PH-H1349-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956"}}],"pack":"ph-p19"};
  FT["PH-H1350"] = {"id":"PH-H1350","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1516_1956.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Fixing a New Period for the Surrender of Treasury Certificates and Central Bank Notes of the Denomination of Over One Hundred Pesos, by Amending Section Two of Republic Act Numbered Eleven Hundred Ninety-One for the Purpose","orig":"An Act Fixing a New Period for the Surrender of Treasury Certificates and Central Bank Notes of the Denomination of Over One Hundred Pesos, by Amending Section Two of Republic Act Numbered Eleven Hundred Ninety-One for the Purpose"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1516","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1516_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1350-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Republic Act Numbered Eleven hundred ninety-one is amended to read as follows:\n\"Sec. 2. To carry out the purposes of this Act, the owners or holders of Treasury certificates and Central Bank notes, either individual persons, associations, corporations, or institutions, of the denominations of over one hundred pesos, are required to surrender them to the Central Bank of the Philippines up to December thirty-one, nineteen hundred fifty-seven, and in exchange to receive from the Bank their equivalent amount in money in Treasury certificates or Central Bank notes of smaller denominations: Provided, That the exchange shall hereafter be allowed only if the holder has not been able to surrender the said notes and/or certificates due his ignorance of the original provisions of Republic Act Numbered Eleven hundred ninety-one or to no fault or negligence on his part or to circumstances beyond his control, or if the holder has acquired said notes and/or certificates for reasons other than speculation: Provided, further, That an affidavit alleging any of said grounds shall be prima facie proof of the facts therein alleged and shall be accepted as sufficient compliance with the preceding proviso.\""}},{"id":"PH-H1350-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In case the affidavit required in the preceding section is found to be false in any material respect, the affiant shall be punished by imprisonment of not less than six months nor more than six years, and by a fine in treble the amount of the certificates and/or notes surrendered in exchange."}},{"id":"PH-H1350-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Central Bank of the Philippines and the provincial and municipal treasurers and barrio councils are hereby directed to give the provisions of this Act wide publicity."}},{"id":"PH-H1350-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
  FT["PH-H1351"] = {"id":"PH-H1351","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1517_1956.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Regulating the Collection, Processing and Sale of Human Blood, and the Establishment and Operation of Blood Banks and Blood Processing Laboratories","orig":"An Act Regulating the Collection, Processing and Sale of Human Blood, and the Establishment and Operation of Blood Banks and Blood Processing Laboratories"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1517","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1517_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1351-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In order to promote public health, it is declared a national policy to prevent trafficking in human blood and its products and derivatives."}},{"id":"PH-H1351-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"As used in this Act:\n\"Blood\" means human blood, processed or unprocessed, and includes its products and derivatives.\n\"Person\" includes corporations, partnerships, associations, and organizations.\n\"Cost\" means the actual purchase price of unprocessed blood and its handling charges, such as those for its collection, processing, storage, transportation, and sale, and a reasonable allowance for spoilage."}},{"id":"PH-H1351-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It shall be the unlawful for any person to establish or operate a blood bank or blood processing laboratory, or to collect or process blood if he is not a licensed physician, or to sell blood collected from another person, even if authorized by the latter, without first securing a license from the Department of Health: Provided, That in cases of emergency, blood transfusion shall be allowed under the responsibility of the attending physician without such license: And Provided, further, That persons operating blood banks and blood processing laboratories on the date of the approval of this Act may continue to operate and same if they secure such license within sixty days from the date of the issuance of the rules and regulations provided for in section five hereof.\nNo license shall be granted or renewed by the Department of Health for the establishment or operation of a blood bank or blood processing laboratory unless such bank or laboratory be established or operated in accordance with accepted scientific standards, is under the administration, direction and supervision of a licensed and qualified physician, and blood is collected and/or processed therein by licensed physicians or under their direct supervision and responsibility.\nNo license shall be granted or renewed by said Department for the collection and/or processing of blood unless the licensee complies with the requirements hereinabove established for blood banks and blood processing laboratories."}},{"id":"PH-H1351-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Blood banks and processing laboratories shall be operated on a non-profit basis. Blood collecting or processing by other blood collectors or processors or by individual physicians shall also be on a non-profit basis. Blood shall be sold by such banks and laboratories, other blood collectors or processors, and individual physicians at cost."}},{"id":"PH-H1351-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Secretary of Health is charged with the responsibility of strictly enforcing this Act, and shall issue such rules and regulations as may be necessary to carry out its provisions, including rules and regulations prescribing, from time to time, the maximum ceilings for handling charges of blood, such as charges for its collection, processing, storage, transportation, and sale, and a reasonable allowance for spoilage, which shall be considered as part of the cost of blood."}},{"id":"PH-H1351-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Any person who violates any provision of this Act or of the rules and regulations issued thereunder shall be punished by imprisonment for not less than one month and not more than one year or by a fine of not less than one hundred pesos and not more than one thousand pesos or by both such fine and imprisonment in the discretion of the court."}},{"id":"PH-H1351-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
  FT["PH-H1352"] = {"id":"PH-H1352","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1518_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Bauan市","en":"An Act Creating the Barrio of San Miguel in the Municipality of Bauan, Province of Batangas","orig":"An Act Creating the Barrio of San Miguel in the Municipality of Bauan, Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1518","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1518_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1352-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The territory bounded on the North by the provincial road from the Municipality of Bauan to the Municipality of Mabini, on the East by a river called Ilog ng Tubigan, on the West by the Sta. Maria River, and on the South by the sea, is separated from the barrios of San Andres and Bolo, Municipality of Bauan, Province of Batangas, and constituted into a barrio of the said municipality to be known as the barrio of San Miguel."}},{"id":"PH-H1352-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
  FT["PH-H1353"] = {"id":"PH-H1353","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1519_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Bacolor市","en":"An Act Creating the Barrio of Mesalipit in the Municipality of Bacolor, Province of Pampanga","orig":"An Act Creating the Barrio of Mesalipit in the Municipality of Bacolor, Province of Pampanga"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1519","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1519_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1353-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Mesalipit in the Municipality of Bacolor, Province of Pampanga, is hereby constituted into a barrio in the said municipality, to be known as the barrio of Mesalipit."}},{"id":"PH-H1353-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
  FT["PH-H1354"] = {"id":"PH-H1354","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1520_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Guagua市","en":"An Act Creating the Barrio of San Rafael in the Municipality of Guagua, Province of Pampanga","orig":"An Act Creating the Barrio of San Rafael in the Municipality of Guagua, Province of Pampanga"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1520","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1520_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1354-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Duck Island in the Municipality of Guagua, Province of Pampanga, is hereby constituted into a barrio of the said municipality, which shall be known as the barrio of San Rafael."}},{"id":"PH-H1354-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
  FT["PH-H1355"] = {"id":"PH-H1355","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1521_1956.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Certain Sections of the Charter of the City of Butuan","orig":"An Act to Amend Certain Sections of the Charter of the City of Butuan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1521","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1521_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1355-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subsections (p) and (ii) of section fifteen of Republic Act Numbered Five hundred twenty-three, otherwise known as the Charter of the City of Butuan, are amended to read as follows:\n\"(p) To tax, fix the license fee for, regulate the business and fix the location of, match factories, blacksmith shops, foundries, steam boilers, lumber mills, lumber yards, rattan yards, logponds or bundles, shipyards, the storage and sale of gunpowder, tar, pitch, resin, coal, oil, gasoline, benzine, turpentine, hemp, cotton, nitroglycerine, petroleum, or any products thereof, and other establishments likely to endanger the public safety or give rise to conflagrations or explosions, and, subject to the rules and regulations issued by the Director of Health in accordance with law, tanneries, renderies, tallow chandleries, embalmers, and funeral parlors, bone factories, and soap factories. As used herein, the term \"logpond or bundle\" means water or place along any bank of any river within the territorial jurisdiction of the city where timber, rattan, bamboos, and other forest products, are placed, stored, tied or rafted together before being towed or moved to ships ready for loading for commercial purposes.\n\"(ii) To extend its ordinance over all waters within the city, over any boat or floating structures thereon, and also over any rafted timber, rattan, bamboos, and other forest products which are being towed either by launches, bancas or barotos up and down the river by manpower, for commercial purposes, by imposing taxes thereon, and, for the purpose of protecting and insuring the purity of the water supply of the city, over all territory within the drainage area of such water supply and within one hundred meters of any reservoir, conduit, canal, aqueduct, or pumping station used in connection with the city water service.\""}},{"id":"PH-H1355-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The second paragraph of section twenty-seven of Republic Act Numbered Five hundred twenty-three, otherwise known as the charter of the City of Butuan is amended to read as follows:\n\"This chief of secret service shall receive a salary of not exceeding two thousand four hundred pesos per annum.\""}},{"id":"PH-H1355-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The first paragraph of section seventy-seven of the said Act is amended to read as follows:\n\"Sec. 77. The clerk and employees of the municipal court. -There shall be a clerk of the Municipal Court who shall be appointed by the municipal judge in accordance with civil service law, rules and regulations, and who shall receive a compensation to be fixed by ordinance, approved by the Secretary of Justice, at not exceeding one thousand eight hundred pesos per annum. He shall keep the seal of the court and affix it to all orders, judgments, certificates, records, and other documents issued by the court. He shall keep a docket of the trials in the court, in which he shall record in a summary manner the names of the parties and the various proceedings in civil cases, and in criminal cases, the name of the defendant, the charge against him, the names of the witnesses, the date of the arrest, the appearance of the defendant, together with the fines and costs adjudged or collected in accordance with the judgment. He shall have the power to administer oath.\""}},{"id":"PH-H1355-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The first paragraph of section eighty-six of the same Act is amended to read as follows:\n\"Sec. 86. The Bureau of Public Schools. -The Director of the Bureau of Public Schools shall exercise the same jurisdiction and power in the city as elsewhere in the Philippines and the Division Superintendent of Schools for the Province of Agusan shall be ex officio superintendent of city schools of Butuan and shall have all the power and duties in respect to the school of their divisions.\""}},{"id":"PH-H1355-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
  FT["PH-H1356"] = {"id":"PH-H1356","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1522_1956.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Emergency Gold Mining Assistance Act of the Philippines","orig":"An Act to Extend the Effectivity of Republic Act Numbered Eleven Hundred Sixty-Four Otherwise Known as the “Emergency Gold Mining Assistance Act of the Philippines” by Amending Section Seven Thereof and to Amend Section Two, Paragraph (A), and Section Four of Said Law"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 1522","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1522_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1356-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two, paragraph (a) of Republic Act Numbered Eleven hundred sixty-four, is hereby amended to read as follows:\n\"Sec. 2. (a) \"Gold producer\" or \"Gold mine\" means any person, corporation, partnership, or association which is producing gold either by itself or through an operating agreement on the date of the approval of this Act or which engages in the production of gold during the effectivity of this Act, either as principal product or as by-product;\""}},{"id":"PH-H1356-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section four of Republic Act Numbered Eleven hundred and sixty-four is amended to read as follows:\n\"Sec. 4. Mines with gold as principal product or as by-product. -Newly-mined gold produced as principal product or as by-product may be sold either to the Government through the Central Bank in the form of refined gold at the current official price per ounce plus the assistance provided in section six hereof or in the domestic free market without benefit of the assistance, at the choice of the gold producer: Provided, However , That at least seventy-five per centum of all newly-mined gold produced by each mine either as principal product or as by-product shall be sold to the Government in accordance with the provisions of this Act: And Provided, further, That mines producing gold as by-product shall only be entitled to the assistance given to mines over the marginal classification.\""}},{"id":"PH-H1356-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Board may, at its discretion, exclude from the benefits of this act any mine which may be found, upon due hearing, to be discriminating in such matter as, but not limited to, salaries, wages and management against Filipino technical men, employees and/or laborers.\""}},{"id":"PH-H1356-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section seven of Republic Act Numbered Eleven hundred sixty-four, is amended to read as follows:\n\"Sec. 7. Term. -This direct short term assistance shall be effective until July 18, 1957.\""}},{"id":"PH-H1356-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
  FT["PH-H1357"] = {"id":"PH-H1357","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1523_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Create the Barrio of Bungahan in the Municipality of Ibaan, Province of Batangas","orig":"An Act to Create the Barrio of Bungahan in the Municipality of Ibaan, Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1523","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1523_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1357-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Bungahan in the Municipality of Ibaan, Province of Batangas, is hereby constituted into a barrio in the said municipality, to be known as the barrio of Bungahan."}},{"id":"PH-H1357-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
  FT["PH-H1358"] = {"id":"PH-H1358","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1524_1956.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting the Manila Times Publishing Company a Franchise to Construct, Maintain and Operate a Radio Broadcasting and Television Stations in the Philippines","orig":"An Act Granting the Manila Times Publishing Company a Franchise to Construct, Maintain and Operate a Radio Broadcasting and Television Stations in the Philippines"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1524","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1524_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1358-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, the Manila Times Publishing Company is hereby granted a franchise which shall continue in force during the time that the Government has not established similar service at the places selected by the grantee, to construct, maintain and operate, for commercial purposes and in the public interest, radio broadcasting and television stations in the Philippines: Provided, That this franchise shall be void unless the construction of at least one radio broadcasting or television station be begun within two years from the date of approval of this Act, and be completed within four years from the said date: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the said radio broadcasting and television stations, to reach the population on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use its stations for the broadcasting of obscene or indecent language or speech, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H1358-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such provisions of Act Numbered Thirty-eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes\"; Act Numbered Thirty-nine hundred and ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred and forty-six, known as the Public Service Act, and their amendments, as are applicable to radio broadcasting and television stations shall be applied, as far as practicable, to the radio broadcasting and television stations referred to in section one."}},{"id":"PH-H1358-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guaranty full compliance and fulfillment of the conditions under which this franchise is granted."}},{"id":"PH-H1358-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall, ipso facto, become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H1358-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on its real estate, buildings, and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay.\n(b) The grantee shall further be liable to pay all other that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H1358-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In the event the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such station or stations to the Government with all the serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1358-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play or other matter to be broadcast or shown from its stations; but if any such speech, play, or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play or other matter: Provided, That the grantee, during any broadcast, may cut off from the air the speech, play, or other matter being broadcast or shown if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral.\""}},{"id":"PH-H1358-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the previous approval of Congress of the Philippines. Any corporation to which this franchise is sold, transferred or assigned; shall be subject to all the conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise has been originally granted to the said person, firm, company, corporation of other commercial or legal entity."}},{"id":"PH-H1358-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
  FT["PH-H1359"] = {"id":"PH-H1359","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1525_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Taytay市","en":"An Act Converting the Sitio of Bambanan, Municipality of Taytay, Province of Palawan, into a Barrio of Said Municipality","orig":"An Act Converting the Sitio of Bambanan, Municipality of Taytay, Province of Palawan, into a Barrio of Said Municipality"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1525","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1525_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1359-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Bambanan, Municipality of Taytay, Province of Palawan, is converted into a barrio of said municipality to be known as the barrio of Bambanan."}},{"id":"PH-H1359-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
