  FT["PH-H1361"] = {"id":"PH-H1361","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1527_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Constituting the Sitios of Calagbenguen, Tarabanan, Bendoyan, Talabigan, Tagbuan and Langogan, Municipality of Puerto Princesa, Province of Palawan, into a Barrio to be Known as Concepcion","orig":"An Act Constituting the Sitios of Calagbenguen, Tarabanan, Bendoyan, Talabigan, Tagbuan and Langogan, Municipality of Puerto Princesa, Province of Palawan, into a Barrio to be Known as Concepcion"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1527","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1527_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1361-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Calagbenguen, Tarabanan, Bendoyan, Talabigan, Tagbuan, and Langogan in the Municipality of Puerto Princesa, Province of Palawan, are constituted into a barrio of said municipality to be known as barrio Concepcion."}},{"id":"PH-H1361-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p19"};
